  Let ARE : 6811648 <= a /\ a + msz <= aceil. Proof. exact (aapp_env _ _ (proj1 AR) ltac:(tlia)). Qed.   (* [comment removed for export] *)
  Let PAE : 6811648 <= pa /\ pa + kPtrArrayReserve <= aceil. Proof. exact (aapp_env _ _ (proj1 PAR) ltac:(clear; hci; unfold kPtrArrayReserve; tlia)). Qed.   (* [comment removed for export] *)
